INSERT IGNORE INTO products (id, exhibitor_id, name, tagline, category, image_url, views, enquiries, interested_visitors_count, overview, features_json, benefits_json, use_cases_json, website_url) VALUES
('prod-mpsedc-1', 'exh-1', 'MP Semiconductor & Fab Policy Incentives', 'State Policy Support for Semiconductor Units', 'State Policy & Grants', '/images/exhibitors/mpsedc.png', 890, 68, 142, 'State-level capital subsidy, subsidized land, dedicated power, and stamp duty exemptions for chip design, OSAT, and fab units in MP.', '["Capital Subsidy up to 50%","Plug-and-play Incubation at Indore","Single-window Approvals"]', '["Faster Time to Market","Significant CAPEX reduction","State-backed infrastructure"]', '["Semiconductor Startups","OSAT Facilities","Fabless Design Houses"]', 'https://mpsedc.mp.gov.in'),
('prod-mpsedc-2', 'exh-1', 'Indore ESDM Innovation & Testing Facility', 'Shared Testing & Characterization Labs', 'Infrastructure', '/images/exhibitors/mpsedc.png', 710, 45, 98, 'World-class shared testing, EMC/EMI validation, and prototyping infrastructure for semiconductor and electronic manufacturers.', '["Shared Cleanroom Facilities","Advanced Measurement Instruments","Technical Mentorship"]', '["Lower barrier to prototype","Certified compliance","Local ecosystem access"]', '["MSMEs","University Spin-offs","Electronic Manufacturers"]', 'https://mpsedc.mp.gov.in'),
('prod-truechip-1', 'exh-truechip', 'PCIe Gen 6 / Gen 7 Verification IP', 'Next-Gen PCI Express Verification Suite', 'Verification IP & EDA', '/images/exhibitors/truechip.png', 840, 65, 138, 'Industry-standard Verification IP for PCI Express Gen 6 and Gen 7 with full PAM4 signaling, FLIT mode, SRIS, and compliance checkers.', '["PAM4 Signaling & 64/128 GT/s FLIT Mode","SystemVerilog / UVM Native Architecture","Advanced Error Injection & Protocol Assertions"]', '["Drastically cuts verification cycle times","Zero protocol ambiguity with full compliance","Proven across 100+ silicon tapeouts"]', '["High Performance Compute (HPC)","AI/ML Accelerators","Data Center & Cloud SoCs"]', 'https://www.truechip.net/product/verification-ip'),
('prod-truechip-2', 'exh-truechip', 'UCIe (Universal Chiplet Interconnect) VIP', 'Turnkey Die-to-Die Chiplet Verification', 'Verification IP & EDA', '/images/exhibitors/truechip.png', 790, 58, 124, 'Comprehensive Die-to-Die (D2D) chiplet verification supporting standard and advanced package architectures, D2D adapter, and physical layers.', '["UCIe 1.0 & 1.1 Multi-die Interconnect Support","D2D Adapter & Protocol Layer Verification","Sideband & Mainband Channel Modeling"]', '["Ensures inter-chiplet interoperability","Rapid integration in standard UVM testbenches","Reduces physical prototyping risks"]', '["Heterogeneous AI Chiplets","Modular Server Processors","Multi-Die Automotive SoCs"]', 'https://www.truechip.net/product/verification-ip'),
('prod-truechip-3', 'exh-truechip', 'CXL 3.1 / 3.0 (Compute Express Link) VIP', 'High-Bandwidth Coherent Interconnect Verification', 'Verification IP & EDA', '/images/exhibitors/truechip.png', 720, 49, 112, 'Complete Verification IP for CXL.io, CXL.cache, and CXL.mem protocols, enabling verification of memory expansion, accelerators, and pooled memory.', '["CXL.io, CXL.cache, and CXL.mem Support","Coherent Memory Fabric Verification","Multi-Logical Device (MLD) Modeling"]', '["Guarantees cache coherency validation","Shortens verification schedule for complex memory architectures","Built-in compliance checking test suites"]', '["Disaggregated Cloud Memory","Accelerated Computing Clusters","Enterprise Storage Systems"]', 'https://www.truechip.net/product/verification-ip'),
('prod-truechip-4', 'exh-truechip', 'USB4 & USB-PD 3.1 Verification IP', 'High-Speed Multi-Protocol Tunneling Verification', 'Verification IP & EDA', '/images/exhibitors/truechip.png', 680, 44, 98, 'Complete USB4 router, adapter layer, and Type-C Power Delivery 3.1 verification IP supporting up to 80 Gbps tunneling of PCIe and DisplayPort.', '["USB4 v2.0 / Gen 4 80 Gbps PAM3 Support","Full USB Type-C and Power Delivery 3.1","Simultaneous PCIe & DisplayPort Tunneling"]', '["Exhaustive test suite for corner cases","Plug-and-play SystemVerilog UVM environment","Field-tested compliance test sequences"]', '["Consumer Electronics SoCs","Smartphones & Laptops","Automotive Infotainment Hubs"]', 'https://www.truechip.net/product/verification-ip'),
('prod-truechip-5', 'exh-truechip', 'HBM3 / LPDDR5X Memory VIP', 'High-Bandwidth Memory Protocol Verification', 'Verification IP & EDA', '/images/exhibitors/truechip.png', 650, 42, 92, 'Turnkey memory verification IP for next-generation AI and mobile memory subsystems, verifying physical and link layers seamlessly.', '["Multi-die HBM3 & LPDDR5X Support","Real-time Timing Assertions & JEDEC Checks","Dynamic Frequency Scaling Verification"]', '["First-pass silicon success","Fast debugging with visual wave tracking","Multi-simulator vendor support"]', '["Edge AI Chips","Mobile 5G Processors","Graphics & Neural Processing Units"]', 'https://www.truechip.net/product/verification-ip'),
('prod-truechip-6', 'exh-truechip', 'RISC-V Verification Suite & TileLink VIP', 'Comprehensive Open-Architecture Core Verification', 'Verification IP & EDA', '/images/exhibitors/truechip.png', 610, 38, 85, 'End-to-end RISC-V processor testbenches covering TileLink cache coherency, JTAG DTM, PLIC/CLINT interrupt controllers, and custom ISA extensions.', '["TileLink TL-UL, TL-UH, and TL-C Support","Custom Instruction & Extension Checkers","Automated Test Generator for Core Pipelines"]', '["Accelerates indigenous silicon design cycles","Validates full processor coherency","Seamless integration with open-source tools"]', '["Indigenous Indian Microprocessors","IoT & Edge Controllers","Custom AI Silicon"]', 'https://www.truechip.net/product/verification-ip'),
('prod-truechip-7', 'exh-truechip', 'TruEye GUI Protocol Debug & Automation', 'Intelligent Visual Protocol Analyzer & Debugger', 'Verification IP & EDA', '/images/exhibitors/truechip.png', 590, 36, 78, 'Proprietary GUI-based protocol debug environment providing transaction-level visualization, performance analytics, and automated packet tracing.', '["Transaction-Level Waveform & Packet Viewer","Real-time Bandwidth & Latency Analytics","Automated Protocol Bug Diagnosis"]', '["Reduces debug cycles by up to 60%","Intuitive graphical trace timeline","Cross-platform support for major EDA tools"]', '["SoC Verification Engineers","Firmware Development Teams","Post-Silicon Validation"]', 'https://www.truechip.net/automation-products.php'),
('prod-cdac-1', 'exh-5', 'VEGA RISC-V Microprocessor Ecosystem', 'Indigenous Open-Architecture Processors', 'R&D & Computing', '/images/exhibitors/cdac.png', 820, 74, 165, 'India''s indigenous 32-bit and 64-bit RISC-V processor family designed by C-DAC under the Microprocessor Development Programme (MDP).', '["Single & Dual Core Variants","Linux & RTOS Support","Integrated Security Blocks"]', '["Sovereign silicon trust","No proprietary architecture royalties","Ideal for strategic electronics"]', '["Smart Energy Meters","Industrial Automation","Strategic Systems"]', 'https://cdac.in'),
('prod-scl-1', 'exh-7', '180nm CMOS Foundry Fabrication', 'Sovereign Silicon Wafer Fab Services', 'Semiconductor Fabrication', '/images/exhibitors/scl.png', 930, 88, 190, 'Full turnkey 180nm CMOS and MEMS wafer fabrication services for strategic, aerospace, and commercial multi-project wafer (MPW) runs.', '["8-inch Wafer Capability","Radiation-Hardened Library","In-house Testing & Packaging"]', '["Domestic fabrication","Space and defense qualified","Regular MPW shuttle runs"]', '["ISRO Satellite Payloads","Defense Microelectronics","Academic MPW Shuttles"]', 'https://scl.gov.in'),
('prod-analog-1', 'exh-50', 'AD9361 High-Performance RF Agile Transceiver', 'Complete SDR Transceiver 70 MHz to 6.0 GHz', 'Analog & Mixed-Signal ICs', '/images/exhibitors/analogdevices.png', 940, 92, 180, 'Highly integrated radio frequency (RF) transceiver capable of wideband communications, point-to-point communication systems, and defense electronics.', '["Dual 12-bit DACs and ADCs","Tunable RF bandwidth 200 kHz to 56 MHz","FDD and TDD Operation"]', '["Compact footprint","Massive BOM reduction","Extensive reference designs"]', '["5G Telecom Infrastructure","Software-Defined Radios","Defense Comms"]', 'https://analog.com'),
('prod-analog-2', 'exh-50', 'LTC6811 Multi-Cell Battery Monitor IC', 'Automotive Precision BMS Silicon', 'Analog & Mixed-Signal ICs', '/images/exhibitors/analogdevices.png', 810, 65, 130, 'Measures up to 12 series connected battery cells with total measurement error under 1.2mV. IsoSPI isolated serial interface enables high-voltage EV packs.', '["AEC-Q100 Qualified","Built-in IsoSPI Isolated Comms","Passive Cell Balancing"]', '["Highest cell voltage accuracy","Maximized EV battery life","ASIL-D compliant design"]', '["Electric Vehicles (2W/3W/4W)","Grid Energy Storage","High-Voltage Industrial Battery Systems"]', 'https://analog.com'),
('prod-teradyne-1', 'exh-40', 'UltraFLEXplus Advanced Test Platform', 'Industry-Leading Semiconductor ATE System', 'ATE & Testing Solutions', '/images/exhibitors/teradyne.png', 790, 60, 140, 'Delivers maximum throughput and lowest cost-of-test for high-complexity AI processors, mobile APs, and automotive automotive radar devices.', '["PACE Multi-Site Architecture","Extreme Pin-Count Density","Ultra-Fast RF Instrumentation"]', '["Fastest yield learning","Reduced test time per device","Proven worldwide production footprint"]', '["OSAT Production Testing","AI Processor Validation","Automotive MCU Screening"]', 'https://teradyne.com'),
('prod-indiesemic-1', 'exh-36', 'Automotive Radar & Sensor Fusion SoC', 'Next-Gen 77GHz Radar Processor', 'Fabless Semiconductor', '/images/exhibitors/indiesemic.png', 660, 48, 115, 'Integrated fabless chip combining multi-channel FMCW radar processing, DSP algorithms, and CAN-FD interface for ADAS safety systems.', '["AEC-Q100 Grade 1","Hardware Radar FFT Accelerator","Integrated Power Management"]', '["Direct sensor-to-ECU telemetry","Compact sensor head design","Optimized power dissipation"]', '["Automotive ADAS","Autonomous Industrial AGVs","Perimeter Surveillance"]', 'https://indiesemic.com'),
('prod-rackbank-1', 'exh-10', 'Green AI GPU Cloud & Datacenter Facility', 'Sustainable Computing for Chip EDA Workloads', 'Data Centers & Cloud', '/images/exhibitors/rackbank.png', 740, 58, 125, 'Tier-3 green datacenter campus located in Indore, Madhya Pradesh offering high-density liquid cooling for massive silicon simulation and EDA regressions.', '["100% Green Energy Pledges","Liquid-Cooled GPU Racks","Ultra-Low Latency Fiber Ring"]', '["Lower operational costs for EDA compute","Secure sovereign Indian cloud hosting","Zero water-waste cooling"]', '["Semiconductor Simulation","AI Model Fine-tuning","Fabless Design R&D Teams"]', 'https://rackbank.com'),
('prod-pine-1', 'exh-44', 'Semiconductor Tapeout & STA Certification', 'Hands-on VLSI Physical Design Masterclass', 'VLSI Training Academy', '/images/exhibitors/pine.png', 630, 50, 112, 'Intensive training program tailored for engineering graduates and VLSI professionals covering advanced synthesis, PnR, Static Timing Analysis, and DRC/LVS.', '["Real PDKs and EDA Tool Flow","Mentorship from Silicon Veterans","100% Placement Record"]', '["Job-ready silicon engineers","Bridges academia-industry gap","Hands-on chip tapeout experience"]', '["Engineering Colleges","Early-career VLSI Engineers","Workforce Skilling Initiatives"]', 'https://pinetrainingacademy.com');
